INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Candy Crush Solitare', 'Candy Crush Solitaire is a fun and challenging classic card game for players of all levels, with a delightful twist to the classic TriPeaks solitaire experience. Join iconic Candy Crush Saga characters in a delicious journey around the world, creating a lovely postcard collection on the way. Relax and immerse yourself in Candy Crush Solitaire''s beautiful graphics, animations, and design!' FROM games WHERE igdb_id = 383749 ON CONFLICT (game_id, language_code) DO NOTHING;
