INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ben Bildim', 'Ben Bildim is a fast-paced, multiplayer trivia game where players compete in real time. Test your knowledge across thousands of unique questions, climb the leaderboard, and prove you’re the ultimate trivia master.' FROM games WHERE igdb_id = 360447 ON CONFLICT (game_id, language_code) DO NOTHING;
