INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rapture Island', 'Rapture Island is a wandering simulator with no goal & intentionally low-quality, retro graphics. It is something that could have been an early 3D game, with graphics reminiscent of the Super FX Chip. Also heavily inspired by poking around Lego Island as a kid, not engaging with any of the main quest.' FROM games WHERE igdb_id = 331106 ON CONFLICT (game_id, language_code) DO NOTHING;
