INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dead Static Drive', 'Dead Static Drive is a horror survival adventure. You''re on the road. The world begins to fall apart in front of you. Your friendships will make every bit of difference as order collapses and the people you meet fight for their own survival. Sneak, scavenge, fight, befriend, barricade and bunker-in or steal a car and drive off into the sunset. There''s no escape; there''s only what you choose to do with the little time that''s left.' FROM games WHERE igdb_id = 25936 ON CONFLICT (game_id, language_code) DO NOTHING;
