INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sunset Sprout', 'Sunset Sprout is a cozy farming simulation game where you rebuild a ruined island and grow it into a thriving paradise. Relax, plant crops, raise animals, craft, and connect with your new community in this charming life sim inspired by the classic farming games of the past.' FROM games WHERE igdb_id = 348460 ON CONFLICT (game_id, language_code) DO NOTHING;
