INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Path of Fury: Episode I - Tetsuo''s Tower', 'Path of Fury is a VR first-person action game focused on hand-to-hand combat. Set in a tower filled with enemies, players fight their way upward using precise, fast strikes. The gameplay emphasizes pattern recognition, endurance, and exploiting enemy weaknesses. While the experience is linear, repeated playthroughs reveal new details and progression elements. The game blends realistic Kung Fu-inspired mechanics with accessible controls, aiming to reward skill and consistency over time.' FROM games WHERE igdb_id = 335485 ON CONFLICT (game_id, language_code) DO NOTHING;
