INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gost! Buster', 'Gost! Buster is a horror game in the genre of psychological thriller, inspired by Russian mythology. You will have to become a ghost hunter, explore the places where the evil dwells, collect clues, determine the type of ghost and conduct exorcism rituals. Use special equipment, fix anomalies and uncover the secrets of the otherworld to rid the world of evil entities forever.' FROM games WHERE igdb_id = 339153 ON CONFLICT (game_id, language_code) DO NOTHING;
