INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Risk & Riches', 'This roguelite deckbuilder is set in the American West. Battle monsters, cultists, and folkloric creatures while searching for gold and the source of the evil within a mine. You choose when to leave, not where to go. Will you play it safe returning to the surface, or risk it all by going deeper?' FROM games WHERE igdb_id = 333646 ON CONFLICT (game_id, language_code) DO NOTHING;
