INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Space Graze', 'Take control of a flying saucer in this retro-style arcade game inspired by classic UFO legends. Circle around grazing cows with your beam, abduct them for fuel, and rack up massive combos! With low-poly 3D visuals and a nostalgic 90s vibe, this game is simple, addictive, and utterly out of this world.' FROM games WHERE igdb_id = 374524 ON CONFLICT (game_id, language_code) DO NOTHING;
