INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mystic Jumper', 'A clumsy wizard miscasts a spell, turning himself into random objects! Now stuck at the bottom of his own tower, he must triple-jump his way to the top to fix his mistake. Master precise platforming, avoid traps, and use unique object physics in this retro pixel-art adventure!' FROM games WHERE igdb_id = 348564 ON CONFLICT (game_id, language_code) DO NOTHING;
