INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Living In Infinity', 'Living In Infinity is a puzzle adventure focused on switching between parallel realities and using various items to solve mysteries. Play as Lin Meizhen, a 17-year-old high school student who eats a suspicious mushroom at home—only to find her familiar surroundings beginning to twist and distort.' FROM games WHERE igdb_id = 369263 ON CONFLICT (game_id, language_code) DO NOTHING;
