INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Time Guard: The Red Menace', 'A time-traveling detective, a brain-hacking device called the Speakbreaker, and a mad plan to make the whole world speak only Russian. Solve absurd puzzles, meet bizarre characters, and rewrite history itself in this comedy point-and-click adventure.' FROM games WHERE igdb_id = 368366 ON CONFLICT (game_id, language_code) DO NOTHING;
