INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Integrifix', 'Catch a falling Core with at least one Shard and heal a broken mind, while you transfer through the abstract memories of your patient. The backgrounds and sounds help you to discover the best moment to send the Shard at the Core. Try gathering Bonuses, and nourish the Integrity Percentage for the Perfect Ending!' FROM games WHERE igdb_id = 335845 ON CONFLICT (game_id, language_code) DO NOTHING;
