INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stick Knight', 'RPG game Twin stick style top down combat, featuring a timed parry system inspired by Sekiro. Plenty of weapons and armor, as well as enemies with different movesets, and (4) challenging bosses. Game length is short enough to complete in ~3-4 days for someone with average skill playing a handful of hours a day.' FROM games WHERE igdb_id = 344809 ON CONFLICT (game_id, language_code) DO NOTHING;
