INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gears of War: Reloaded', 'The original Gears of War returns, faithfully remastered and natively optimized for more platforms than ever before as Gears of War: Reloaded. Experience the origins of one of gaming’s most acclaimed franchises like never before. Featuring 4K resolution, up to 120 FPS support, and the ultimate multiplayer experience with cross-progression and cross-play, across all platforms, this is the definitive way to experience the game that started it all.' FROM games WHERE igdb_id = 342721 ON CONFLICT (game_id, language_code) DO NOTHING;
