INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Victim.exe', 'This executable, named "victim", was found in the deep corners of the internet. It contained a severely corrupted maze game. Though there are many, only one level of this game was able to be shared, as the other half-corrupted levels were not safe for viewing and caused multiple seizures to the people recovering them. Almost 20 audio files were also removed as most were too disturbing for listening, including a 32-minute-long file of several children screaming.' FROM games WHERE igdb_id = 335344 ON CONFLICT (game_id, language_code) DO NOTHING;
