INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Stone of Madness', 'From the studio that brought you the Blasphemous series comes The Stone of Madness: a real-time tactical stealth game set in an 18th-century Spanish Monastery. Located in the Pyrenees, this time-worn Jesuit monastery is home to a madhouse and an inquisitorial prison. Five prisoners - plagued by cruel punishment, madness, and despair - pool their skills and resources to face their phobias, stave off insanity, uncover the mysteries of the Monastery, and find a way to escape.' FROM games WHERE igdb_id = 138097 ON CONFLICT (game_id, language_code) DO NOTHING;
