INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Saint Seiya EX', 'Officially licensed by Toei Animation, Saint Seiya EX is a 3D remade strategy card game. Featuring CG-quality 3D visuals, it aims to faithfully recreate the audio-visual experience of the anime, and bring the Sanctuary world to life. Every character can evolve into SSR: everyone can unleash the power of Cosmo! Now, begin your journey to protect Athena once again—gather your team, wear your Cloth, relive the legend, and forming a brand-new Saints'' crew to win the Sanctuary War!' FROM games WHERE igdb_id = 377810 ON CONFLICT (game_id, language_code) DO NOTHING;
