INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lost Altr', 'LOST ALTR is a solo rogue-lite card game set within the crumbling halls of a forgotten temple. You’ll face a series of Trials—mysterious encounters drawn from an ever-shifting deck. Each completed Trial leads you deeper into the Ruins of ALTR. Use Aspect cards to shape your fate—mysterious forces that grant you powerful advantages, but always at a cost.
