INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Maths Pals', 'Embark on an exciting math adventure with six lovable animal friends, each a master of their own math skill! From counting and addition to multiplication and division, explore 20 levels per topic, starting with simple visuals like fingers and dice, and working up to complex challenges with numbers up to 25x25. Earn stars for every correct answer, improve your score, and choose your own path to learning success. Visit each pal at their cozy home and let them guide you through fun, interactive quizzes designed to make math magical!' FROM games WHERE igdb_id = 341278 ON CONFLICT (game_id, language_code) DO NOTHING;
