INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Skull-Rung', 'Laura''s landed the job of her dreams as junior partner to Amy, a trailblazing marketing exec. Laura''s convinced she''s finally going to make her name and escape the grey mire her life has become. Amy has other plans. A workplace thriller intended for adult audiences. Submitted to the Toxic Yuri VN Jam 2025.' FROM games WHERE igdb_id = 355334 ON CONFLICT (game_id, language_code) DO NOTHING;
