INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Speed Rivals', 'Speed Rivals is an arcade-style slot racing game where players control miniature cars fixed on rails, adjusting their speed to master corners and outpace their rivals. Inspired by classic toy car tracks, the game offers a mix of fast-paced competition and creative freedom. Players can unlock and customize dozens of unique vehicles, race through themed environments, and even build their own tracks. With multiplayer modes, community tournaments, and a growing garage of cars from pop culture and racing history, Speed Rivals brings the thrill of slot racing to a new generation.' FROM games WHERE igdb_id = 348939 ON CONFLICT (game_id, language_code) DO NOTHING;
