INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Drill Bird', 'Drill Bird is a cozy-yet-tense digging platformer where every trip underground counts. Fallen from the sky, you search for powerful ores to hatch your egg. Bring them home, upgrade abilities, grow stronger, and unravel a story about survival, care, and purpose. Exploring, returning, and growing.' FROM games WHERE igdb_id = 351078 ON CONFLICT (game_id, language_code) DO NOTHING;
