INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'DoomCrush', 'Step into the chaotic rhythm of DOOMCRUSH, a visually striking arcade experience where every tap is a fight for survival. This high-intensity game blends fast reflexes with a meta-narrative twist, as you battle against time, destruction, and the game’s own rebellious antagonist, Dystro—who wants nothing more than to erase himself from existence.' FROM games WHERE igdb_id = 360548 ON CONFLICT (game_id, language_code) DO NOTHING;
