INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'For God''s Sake, Help Him!', 'FOR GOD''S SAKE, HELP HIM! is a tiny, surreal first-person art "game" about what it''s like. your goal is singular and simple: try to help him, however you can... if you can. that''s a tall order considering you''re both in a blank void and he''s being crushed over and over.' FROM games WHERE igdb_id = 373647 ON CONFLICT (game_id, language_code) DO NOTHING;
