INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Survive Till 100 Years Old', 'How hard is it to "survive" to 100? This match-3 strategy game brings the answer with fun and challenges! In the game, players must use match-3 mechanics to gain nutrition, maintain health, and acquire skills to survive. Wisdom and strategy might help you achieve the goal, but luck is indispensable!' FROM games WHERE igdb_id = 339117 ON CONFLICT (game_id, language_code) DO NOTHING;
