INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fushigi na Sekai no Kankou Nikki II: Pakuru World to Sejika no Gyakushuu', 'Fushigi na Sekai no Kankou Nikki II: Pakuru World to Sejika no Gyakushuu is a multi-genre game that combines various gameplay elements. It features clicker mechanics, fishing, sushi-themed rhythm segments, quick-time events, car chases, shooting, deduction and memory challenges, slot machine gameplay, character development, RPG elements, ninja-themed sequences, action segments, and bullet hell-style dodging. This diverse mix of game styles aims to provide a varied and engaging experience for players.' FROM games WHERE igdb_id = 346376 ON CONFLICT (game_id, language_code) DO NOTHING;
