INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crossbars', 'Get ready for the ultimate downhill mountain biking experience in Crossbars, where speed, skill, and adventure collide. Set across four stunning, mountainous islands, Crossbars challenges you to race through 20 thrilling tracks, each with its own unique terrain and environmental hazards. From rocky cliffs and forested trails to muddy paths and open hills, every track offers a new adventure—will you stick to the main path and race against the clock, or venture off-road and discover hidden secrets?' FROM games WHERE igdb_id = 353963 ON CONFLICT (game_id, language_code) DO NOTHING;
