INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Left Right', 'A voice says either "left" or "right." Click the corresponding arrow: left or right. The voice will say another at the same time, and it keeps going. This is a test of hand-eye coordination. Or hand-ear coordination? See how fast you can play without messing up! It''s easy, right? That''s all I got left.' FROM games WHERE igdb_id = 347283 ON CONFLICT (game_id, language_code) DO NOTHING;
