INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blanket Fort', 'BLANKET FORT is a single player, first-person horror exploration game. Navigate a cozy maze of blankets and pillows which grow increasingly claustrophobic as you help plushies with their troubles but be careful - keep your favorite teddy close or he might get jealous. Don’t get lost… or found.' FROM games WHERE igdb_id = 355539 ON CONFLICT (game_id, language_code) DO NOTHING;
