INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('shantae-advance-risky-revolution--1', 276506, '2025-08-19', 81, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coaboc.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3l7z.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shantae Advance: Risky Revolution', 'Shantae is back in an adventure 20 years in the making! The nefarious pirate Risky Boots has a “groundbreaking” new plan that will leave Sequin Land spinning — by rotating the continent, she can move any town right to the coast for easy plundering! As Shantae, turn the tectonic tables on Risky by taking control of the land itself: shift, twist, navigate, and explore by swapping between mix-and-match multilayered levels! Hair-whip and belly-dance your way through scrambled lands, misplaced towns, monster-filled crypts, and daunting labyrinths. Six creature transformations, fierce boss battles, and a 4-player versus mode await!' FROM games WHERE igdb_id = 276506 ON CONFLICT (game_id, language_code) DO NOTHING;
