INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crystal Ball of Firmament', 'The spell book is missing! Help the magician to find it in this action platformer adventure. Use the crystal ball to change between the day and night to make your path, collect tokens and buy useful upgrades. Venture out 4 different biomes (mountain, woods, winter forest and city) with a total of 32 levels. Warping the day / night cycle changes ambiental obstacles and enemies behavior.' FROM games WHERE igdb_id = 335189 ON CONFLICT (game_id, language_code) DO NOTHING;
