INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dating Stories', 'Dating Stories combines the fun of solving jigsaw puzzles with the spicy excitement of romantic interactions with the sexiest women you can imagine. Piece together well-drawn images of your accidental dates to unlock seductive conversations and deepen your connections. Every choice you make in dialogues shapes your relationships, leading to a tempting ending. With gorgeous artwork and steamy, suggestive content, Dating Stories gives an experience for those seeking both charm and challenge.' FROM games WHERE igdb_id = 332167 ON CONFLICT (game_id, language_code) DO NOTHING;
